import json
import sys

def extract_s3_getobject_principals(policy_json):
    try:
        policy = json.loads(policy_json)
    except json.JSONDecodeError:
        return []

    principals = set()

    if 'Statement' not in policy:
        return sorted(list(principals))

    for statement in policy['Statement']:
        if not isinstance(statement, dict):
            continue

        actions = statement.get('Action', [])
        if isinstance(actions, str):
            actions = [actions]

        has_get_object = False
        for action in actions:
            if action == 's3:GetObject' or action == 's3:*' or action == '*':
                has_get_object = True
                break

        if not has_get_object:
            continue

        principal = statement.get('Principal')

        if principal is None:
            continue

        if isinstance(principal, str):
            if principal != '*':
                principals.add(principal)
        elif isinstance(principal, dict):
            if 'AWS' in principal:
                aws_principals = principal['AWS']
                if isinstance(aws_principals, str):
                    principals.add(aws_principals)
                elif isinstance(aws_principals, list):
                    principals.update(aws_principals)

            if '*' in principal:
                pass
        elif isinstance(principal, list):
            for p in principal:
                if isinstance(p, str) and p != '*':
                    principals.add(p)

    return sorted(list(principals))


if __name__ == '__main__':
    policy_input = sys.stdin.read()
    result = extract_s3_getobject_principals(policy_input)
    print(json.dumps(result))
